INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Uso de WhatsApp para Avanzar la Venta', 'En Latinoamérica, WhatsApp es el canal de comunicación preferido. El vendedor debe ser breve, educativo y dejar una pregunta de avance. El objetivo no es cerrar en WhatsApp, sino avanzar a una llamada o reunión. El mensaje debe conectar con el dolor del cliente y ofrecer valor inmediato.', '"Hola [nombre], vi tu consulta sobre INVU. Entendemos que cada negocio en Latinoamérica tiene sus propias necesidades. ¿Me puedes contar cuántos locales tienes y qué sistema usas hoy? Con eso te comparto casos de éxito de negocios similares al tuyo en tu país." El cliente responde y el vendedor agenda una llamada. El WhatsApp es la puerta de entrada.', NULL, NULL, NULL, 1);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Llamada de 20 Minutos que Cierra', 'En una llamada de ventas en Latinoamérica, el vendedor debe controlar el ritmo: 5 minutos de diagnóstico, 5 de educación, 5 de comparación, 5 de construcción de valor, y cerrar con una pregunta de avance. La llamada no es una presentación de producto; es una solución de problemas. El objetivo es terminar con una reunión agendada o una decisión de compra.', 'Un vendedor llama a un dueño de restaurante en Lima. En 5 minutos, diagnostica: 2 locales, sistema básico, paga Nubefact. En 5 minutos, educa sobre FE nativa. En 5 minutos, compara: S/450 vs S/350. En 5 minutos, construye valor: ahorro de mermas y comisiones. Cierra: "¿Qué día te acomoda para la demo?" El cliente agenda. La llamada de 20 minutos avanza la venta.', NULL, NULL, NULL, 2);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Demo Presencial que Conecta con el Espacio del Cliente', 'En una reunión presencial en Latinoamérica, el vendedor debe llevar una demostración física del sistema, preferiblemente en el equipo del cliente. La demo no es un recorrido por todas las funcionalidades; es una conexión con el espacio del cliente. Se muestra cómo INVU resolvería los dolores específicos identificados en el diagnóstico. Se invita al cliente a tocar el sistema y hacer preguntas.', 'Un vendedor visita un restaurante en Bogotá. Lleva una tablet con INVU instalado. No hace una demo genérica; muestra cómo centralizaría los 2 locales del cliente, cómo el KDS organizaría la cocina, cómo el QR agilizaría los pedidos en mesa. El cliente toca la tablet, ve su propio menú cargado, y visualiza su operación con INVU. La demo termina con una cotización y un plan de implementación.', NULL, NULL, NULL, 3);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Caso del Restaurante con Delivery y Ecommerce', 'Un restaurante con 2 locales, facturación de S/150,000, delivery por apps y ecommerce desconectado del sistema, es un cliente ideal para INVU. El vendedor debe mostrar que INVU integra todo: POS, inventario, delivery, ecommerce y fidelización en una sola plataforma. El argumento es que el costo de INVU es menor que el costo de mantener sistemas separados y que las herramientas de INVU generarán ingresos adicionales que cubrirán la inversión.', 'El vendedor dice: "Con INVU, delivery y ecommerce se integran automáticamente. Los pedidos entran solos, el inventario se actualiza sin intervención, y tú tienes datos en tiempo real desde tu celular. El ahorro de tiempo y la reducción de errores justifican la inversión. Te propongo que hagamos una demostración enfocada en cómo integrarías delivery, ecommerce y tus 2 locales."', NULL, NULL, NULL, 4);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Manejo de la Objeción "Es Caro para Mi Tamaño"', 'El cliente que dice "es caro para mi tamaño de negocio" está comparando el precio de INVU con su facturación actual, sin ver el valor a largo plazo. El vendedor debe validar la preocupación, educar sobre la escalabilidad de INVU, comparar con el costo de sistemas separados, construir valor mostrando el ahorro en tiempo y el incremento en ventas, y cerrar con una pregunta de avance.', '"Entiendo que el presupuesto es importante. INVU es escalable: empiezas con lo que necesitas hoy: POS e inventario. Cuando crezcas, activas delivery, ecommerce, fidelización. No pagas por lo que no usas. Un sistema simple te va a costar menos ahora, pero te va a dar problemas de integración. Cuando necesites delivery o ecommerce, vas a tener que pagar sistemas separados. INVU ya los tiene integrados."', NULL, NULL, NULL, 5);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Manejo de la Objeción "Lo Voy a Pensar"', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El vendedor debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, construir valor ofreciendo una demo sin compromiso, y cerrar con una pregunta de avance para agendar la reunión.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener integración es mayor que el costo de implementarla. Cada mes sin integración es un mes de doble trabajo, inventario desactualizado y oportunidades perdidas. Pensarlo cuesta tiempo y dinero. No te pido que decidas hoy. Te pido que le des la oportunidad a INVU de demostrarte su valor en una reunión."', NULL, NULL, NULL, 6);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Rol del Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', NULL, NULL, NULL, 7);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Pitch de 30 Segundos que Abre Puertas', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', NULL, NULL, NULL, 8);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', NULL, NULL, NULL, 9);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Facturación Electrónica Nativa – El Ahorro que el Cliente No Ve', 'El 70% de los restaurantes en Perú paga aparte por su facturación electrónica (S/89-149/mes). INVU incluye FE nativa sin límite de documentos. El Hunter debe mostrar que el costo de la competencia incluye un PSE externo que INVU ya tiene integrado. Cuando el cliente compara precios, el Hunter debe sumar ese costo oculto para mostrar el ahorro real.', 'Un cliente dice: "El POS X es más barato que INVU." El Hunter responde: "¿X incluye facturación electrónica nativa o pagas aparte a Nubefact o Efact?" El cliente admite que paga S/120/mes por Nubefact. El Hunter suma: "Entonces X te cuesta S/250 + S/120 + S/80 de soporte = S/450/mes. INVU es S/350/mes todo incluido. Termina siendo más barato." El cliente se queda pensando.', NULL, NULL, NULL, 10);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Llave en Mano – La Implementación que Diferencia', 'INVU no entrega un software para que el cliente lo configure; lo deja operando. Configuración completa, carga de menú con recetas, instalación de equipos, capacitación y go live acompañado. La competencia vende licencias y deja solo al cliente. El Hunter debe comunicar que INVU no es un software; es una operación lista para facturar.', '"La competencia te vende licencias y te deja solo. INVU te deja el restaurante operando desde el día uno. Nosotros configuramos, cargamos tu menú con recetas y costos, instalamos equipos, capacitamos a tu personal y estamos contigo el día del arranque. No pagas por un software, pagas por una operación lista para facturar." El cliente, que no tiene tiempo para configurar sistemas, valora el servicio.', NULL, NULL, NULL, 11);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Onboarding Consultivo – Costear para Ganar', 'INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio.', NULL, NULL, NULL, 12);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Soporte Local 24/7 – El Seguro de Continuidad', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', NULL, NULL, NULL, 13);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Ecosistema Móvil Nativo – El Negocio en el Bolsillo', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', NULL, NULL, NULL, 14);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', NULL, NULL, NULL, 15);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Escalera Base – Protección para el Hunter', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258. No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', NULL, NULL, NULL, 16);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Comisiones desde la Venta 4 – El Ingreso sin Techo', 'Desde la cuarta venta, el Hunter gana 10% sobre setup facturado y pagado, 3% MRR mensual sobre licencias activas durante 12 meses, y 3% sobre hardware. Las comisiones se suman a la base, no la reemplazan. El ingreso del Hunter no tiene techo: cada venta adicional es puro ingreso incremental.', 'Un Hunter cierra 7 ventas en un mes. Base: S/2,958. Comisiones de setup de las ventas 4 a 7: 10% de S/700 = S/980. Bono Top Performer: S/1,020. Cola MRR de las licencias activas: S/504. Ingreso total: S/5,462. Cada venta adicional es puro ingreso extra. No hay techo.', NULL, NULL, NULL, 17);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El MRR – Ingresos Pasivos que se Construyen', 'El 3% MRR se paga mensualmente durante 12 meses sobre las licencias activas de cada cliente que el Hunter trajo. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional.', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin esfuerzo adicional.', NULL, NULL, NULL, 18);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Bonos – Gasolina Extra para el Esfuerzo', 'Bonos escalonados: Bono de Inicio S/408 (3 ventas en primer mes), Ejecutivo Ideal S/850 (5 ventas/mes), Top Performer S/1,020 (7 ventas/mes), Bono Trimestral S/3,400 (promedio 10 ventas/mes). Los bonos transforman un buen mes en un mes excepcional y recompensan la consistencia.', 'Un Hunter tiene un mes con 7 ventas. Base: S/2,958. Comisiones: S/980. Bono: S/1,020. Total: S/4,958. Si mantiene 10 ventas/mes en el trimestre, gana S/3,400 adicionales. La diferencia entre 5 y 7 ventas es S/170 de bono extra; entre 7 y 10, el bono trimestral de S/3,400. El esfuerzo adicional se paga solo.', NULL, NULL, NULL, 19);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', '"Venta Grande Vale por Tres" – Apunta a lo Grande', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (ej. una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas.', NULL, NULL, NULL, 20);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', NULL, NULL, NULL, 21);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Ritmo del Hunter Ganador', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base S/2,958 + comisiones S/490 + bono S/850 + MRR S/252 = S/4,550. El esfuerzo se traduce en dinero.', NULL, NULL, NULL, 22);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Comparación con Números – El Argumento del Ahorro', 'El Hunter debe comparar INVU con las alternativas del mercado peruano con datos concretos. Sumar el costo del PSE externo, el soporte aparte y las horas de configuración que la competencia no incluye. Mostrar que INVU (S/350/mes todo incluido) es más barato que la competencia (S/450/mes con PSE y soporte). La diferencia de S/100 es el 0.2% de la facturación de un restaurante de S/50,000.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene. Esa diferencia de S/100 al mes es el 0.2% de tu facturación."', NULL, NULL, NULL, 23);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Es Caro" – El Protocolo Gravity', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity para "es caro" tiene 5 pasos: Validar (entiendo que el precio es importante), Diagnosticar (¿qué te parece caro exactamente?), Reencuadrar (cuando sumas el PSE, el costo real es mayor), Micro-cierre (¿te parece si hacemos el cálculo con tus números?), y Cierre (¿qué día te acomoda para la demo?).', 'Cliente: "Es caro."  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Ya Tengo un POS" – Diagnosticar el Dolor', 'El cliente que dice "ya tengo un POS" no está cerrado; está diciendo que no ve razón para cambiar. El Hunter debe diagnosticar qué le falta a su sistema actual. Preguntas: "¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real?" Si no tiene esas funcionalidades, INVU es una mejora.', '"Me alegra que tengas un sistema. ¿Tu sistema actual incluye facturación electrónica nativa o pagas aparte? ¿Puedes centralizar varias sedes desde un solo panel? ¿Tienes control de inventario en tiempo real? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. No se trata de cambiar por cambiar. Se trata de tener una operación rentable."', NULL, NULL, NULL, 25);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Objeción "Lo Voy a Pensar" – El Costo de la Postergación', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El Hunter debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, y cerrar ofreciendo una demo sin compromiso.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos."', NULL, NULL, NULL, 26);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Setup – Inversión, No Gasto', 'El setup de INVU es un desembolso inicial que muchos clientes ven como un gasto. El Hunter debe reencuadrarlo como una inversión que ahorra meses de operación rota. La competencia no cobra setup porque no hace nada: da el software y el cliente lo configura. INVU cobra setup porque deja el restaurante operando desde el día uno.', '"Entiendo que el setup es un desembolso inicial importante. Ese setup lo pagás una vez y te ahorra meses de operación rota. Además te lo podemos plantear como facturación anual con mejor precio. La competencia no cobra setup porque no hace nada: te dan el software y tú lo configuras. INVU te deja el restaurante operando desde el día uno. El setup es inversión, no gasto."', NULL, NULL, NULL, 27);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al Hunter profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al Hunter con datos reales.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', NULL, NULL, NULL, 28);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Caso del Restaurante con Facturación Externa y Múltiples Sedes', 'Un cliente con 3 sedes que paga Nubefact aparte y no tiene control centralizado es el cliente ideal para INVU. El Hunter debe mostrar que el costo actual (S/1,110/mes) es solo un poco menor que INVU (S/1,862/mes), pero que INVU incluye centralización, FE nativa, KDS y Loyalty. El ahorro en mermas (2% = S/2,400/mes) y comisiones de delivery cubren la diferencia.', '"Entiendo que el costo de INVU es mayor que lo que pagas hoy. Hoy pagas S/1,110 mensuales: S/750 por los 3 POS y S/360 por Nubefact. Con INVU, el costo mensual es S/1,862, que incluye centralización, FE nativa, KDS y Loyalty. La diferencia es S/752, que es el 0.6% de tu facturación mensual. Pero lo que no estás viendo es lo que te cuesta no tener centralización: precios desactualizados, inventario que no cuadra, mermas sin control. Si reducimos tus mermas en un 2%, son S/2,400 mensuales de ahorro. La inversión se paga sola."', NULL, NULL, NULL, 29);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Errores que Matan la Venta', 'Hay 6 errores comunes que el Hunter debe evitar: Hablar de precio antes de diagnosticar; hacer una demo genérica sin enfocarse en el dolor; no sumar los costos ocultos de la competencia; no comparar con la competencia local; no cerrar con una pregunta de avance; hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza".', 'Un cliente pregunta: "¿Cuánto cuesta?"  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Los Niveles de Dominio – De Básico a Gravedad Cero', 'El Hunter pasa por 4 niveles: Básico (explica el producto sin conectar beneficios), Medio (conecta beneficios y diagnostica), Alto (justifica el precio y maneja objeciones con autoridad), y Gravedad Cero (controla la conversación y cierra con autoridad, sin descuentos). El objetivo es llegar a Gravedad Cero: ser un asesor estratégico del restaurantero, no un vendedor más.', 'Básico: "INVU tiene facturación electrónica nativa."  
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Programa de Referidos – La Puerta de Entrada sin Esfuerzo', 'El Programa de Referidos INVU está diseñado para que cualquier persona con contactos en la industria gastronómica pueda monetizar su red sin necesidad de ser vendedor. El referidor no vende, no hace demos, no cotiza y no implementa. Su única función es abrir la puerta: identificar un negocio que califique, contactar al tomador de decisión, presentar a INVU como el socio recomendado, y asegurar una reunión. El equipo de INVU hace el resto. Es el programa de referidos más simple y accesible del mercado peruano.', 'Un cliente satisfecho de INVU, dueño de un restaurante, conoce a otro restaurador que tiene problemas con su facturación electrónica. El cliente le dice: "Oye, INVU me cambió la vida. Te recomiendo que los conozcas. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El restaurador acepta. El cliente envía un correo a INVU con los datos de contacto. El equipo de INVU agenda la reunión, cierra la venta, y el cliente referidor cobra S/1,000 sin haber hecho nada más que abrir la puerta.', NULL, NULL, NULL, 32);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Comisiones Fijas – Transparencia Total', 'El referidor cobra una comisión fija según el tamaño del negocio: S/500 para negocio pequeño (1-2 sedes), S/1,000 para negocio en crecimiento (3-5 sedes), S/1,500 para cuenta consolidada (más de 5 sedes). No hay porcentajes variables, no hay condiciones de permanencia, no hay pagos fraccionados. El referidor sabe exactamente cuánto va a ganar desde el momento en que identifica el negocio. Esta transparencia es un diferenciador clave frente a otros programas de referidos.', 'Un proveedor de insumos conoce a una cadena de 10 restaurantes. Sabe que si refiere ese negocio a INVU, cobrará S/1,500 cuando el cliente firme y pague su primera factura. No tiene que calcular porcentajes ni preocuparse por si el cliente se mantiene 6 o 12 meses. El cálculo es simple: S/1,500. Esta claridad lo motiva a hacer la referencia.', NULL, NULL, NULL, 33);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Protección de Oportunidad – 90 Días de Exclusividad', 'El referidor que registra primero un negocio queda como propietario de esa oportunidad durante 90 días. Si el negocio avanza y cierra dentro de ese plazo, la comisión es para el referidor que lo registró. Esto elimina la competencia desleal y protege el esfuerzo del referidor. Es la garantía de que su trabajo no será aprovechado por otro.', 'Un referidor identifica un restaurante de 3 sedes, contacta al dueño, y registra la oportunidad en INVU mediante correo a lizeth@invupos.com. Dos semanas después, otro referidor intenta registrar el mismo negocio. INVU verifica que el primero ya lo tiene registrado y protege la oportunidad del referidor original. Este último tiene la tranquilidad de que su comisión está asegurada si el negocio cierra dentro de los 90 días.', NULL, NULL, NULL, 34);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Proceso de 3 Pasos – Simple y Sin Complicaciones', 'El programa de referidos tiene un proceso simple de tres pasos: Preséntanos (contacta al decisor y presenta a INVU), Facilita los datos (envía contacto e información clave a INVU), Asegura la cita (deja la reunión agendada). De ahí en adelante, INVU toma el control. El referidor no tiene que hacer demos, ni cotizaciones, ni seguimiento comercial. El proceso es tan simple que cualquier persona, sin importar su experiencia en ventas, puede participar.', 'Un contador con clientes restauranteros quiere referirlos a INVU. No sabe cómo hacer una demo ni cómo manejar objeciones técnicas. Pero el proceso de 3 pasos es simple: 1) Contacta a su cliente dueño de un restaurante y le dice que INVU es el sistema que recomienda. 2) Envía un correo a lizeth@invupos.com con los datos del cliente. 3) Agenda una reunión entre el cliente y el equipo de INVU. El contador no necesita saber nada más; INVU hace el resto.', NULL, NULL, NULL, 35);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Perfil del Cliente Ideal para Referir', 'El referidor debe enfocar sus esfuerzos en negocios que califiquen: restaurantes, bares, cafeterías, franquicias, cadenas de comida, o comercios gastronómicos que facturen al menos S/30,000 mensuales. Si el negocio no cumple con este perfil, probablemente no sea un buen cliente para INVU y el referidor perderá tiempo. Identificar el perfil correcto es el primer paso para maximizar la efectividad del referidor.', 'Un referidor conoce a un amigo que tiene una pequeña cafetería que factura S/10,000 mensuales. Sabe que este negocio no califica para INVU, así que no pierde tiempo refiriéndolo. En cambio, enfoca sus esfuerzos en otro contacto: un dueño de una cadena de 5 restaurantes que factura S/150,000 mensuales. Este sí califica y el referidor puede ganar S/1,000 por la referencia.', NULL, NULL, NULL, 36);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'Las 7 Preguntas del Referidor – Calificar Antes de Referir', 'El referidor debe hacer 7 preguntas de diagnóstico antes de referir un negocio: sector gastronómico o comercial, número de sedes, facturación mensual, sistema actual y dolor, tomador de decisión, problemas específicos (facturación, inventario, centralización, retención de clientes), y planes de crecimiento. Estas preguntas aseguran que el negocio califica y que INVU tiene una oportunidad real de cerrar la venta.', 'Un referidor contacta a un conocido dueño de un restaurante. En lugar de referirlo inmediatamente, hace las 7 preguntas: "¿Cuántas sedes tienes? ¿Qué sistema usas hoy? ¿Cómo manejas la facturación electrónica? ¿Tienes recetas costeadas? ¿Quién toma las decisiones? ¿Tienes planes de abrir más locales?" Al obtener las respuestas, el referidor confirma que el negocio califica y que el dolor principal es la falta de centralización. Ahora puede presentar a INVU de manera más efectiva, enfocándose en ese dolor.', NULL, NULL, NULL, 37);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Mensaje que Abre Puertas – Presentación Sin Presión', 'El referidor debe presentar a INVU de manera atractiva pero sin presión, conectando con el dolor del negocio. Un buen mensaje es: "Conozco a INVU POS, es el sistema que usan más de 5,000 restaurantes en Latam. Son especialistas en restaurantes, incluyen facturación electrónica nativa y te dejan el negocio operando desde el día uno. Creo que pueden ayudarte con [el dolor específico]. Te recomiendo que los conozcas." Esta presentación es breve, clara y enfocada en el beneficio.', 'Un referidor le dice a un dueño de restaurante: "Oye, sé que has tenido problemas con el inventario y la facturación electrónica en tus 3 locales. Te quiero recomendar INVU POS, el sistema que usamos en mi restaurante. Nos cambió la vida: incluimos facturación electrónica nativa sin pagar extra a Nubefact, centralizamos el inventario de los 2 locales, y vemos reportes en tiempo real desde el celular. ¿Quieres que los contacte para que te hagan una demo sin compromiso?" El dueño, que confía en el referidor, acepta.', NULL, NULL, NULL, 38);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Cierre del Referidor – Asegurar la Reunión', 'El cierre del referidor no es cerrar una venta; es asegurar una reunión. El referidor debe preguntar: "¿Te parece si los contacto para que te hagan una demo enfocada en tu negocio? No hay compromiso, solo conoces la solución. ¿Qué día te acomoda?" Cuando el referidor asegura la reunión, su trabajo está hecho. Luego registra la oportunidad en INVU y espera su comisión.', 'Un referidor ha presentado INVU a un colega restaurador. El colega muestra interés. El referidor cierra: "¿Qué te parece si les paso tu contacto para que te llamen y agenden una reunión? Ellos se encargan de todo. ¿Te parece bien? ¿Qué día te acomoda?" El colega dice: "El jueves a las 10am." El referidor envía el correo de registro a INVU y su comisión está protegida.', NULL, NULL, NULL, 39);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Registro Correcto – Protege tu Comisión', 'El referidor debe registrar la oportunidad formalmente mediante correo a lizeth@invupos.com con copia a jorge@invupos.com, incluyendo: nombre del negocio, nombre y cargo del tomador de decisión, teléfono y correo de contacto, número de sedes, facturación aproximada, y sistema actual. Sin este registro, la comisión del referidor no está protegida. Lo que no está registrado, no existe.', 'Un referidor asegura una reunión con un dueño de restaurante, pero no envía el correo de registro. Dos semanas después, otro referidor registra el mismo negocio. El primero pierde la comisión porque no protegió su oportunidad. El segundo referidor, que sí registró, cobra S/1,000 cuando el negocio cierra. El referidor que no registró aprende la lección.', NULL, NULL, NULL, 40);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Valor del Esfuerzo vs. la Comisión', 'El referidor invierte entre 1 y 3 horas para identificar, contactar, presentar y registrar un negocio. Por ese esfuerzo, puede ganar S/500, S/1,000 o S/1,500. La tasa de retorno es de S/167 a S/500 por hora, muy superior al ingreso promedio en Perú. Si el referidor mantiene una red de contactos activa y refiere negocios regularmente, puede generar un ingreso complementario significativo con bajo esfuerzo.', 'Un contador refiere 1 negocio pequeño al mes (S/500). Son 3 horas de trabajo al mes. Ingreso anual: S/6,000. Si refiere 1 negocio en crecimiento al mes (S/1,000), son S/12,000 anuales. Si refiere 1 cuenta consolidada al mes (S/1,500), son S/18,000 anuales. Todo con 3 horas de trabajo al mes. El esfuerzo es mínimo; el retorno es alto.', NULL, NULL, NULL, 41);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Riesgo Cero para el Referidor', 'El referidor no asume ningún riesgo financiero. No invierte dinero, no firma contratos, no garantiza el pago del cliente. Su único riesgo es que el negocio referido no cierre dentro de los 90 días, lo que significaría que su esfuerzo de 1-3 horas no rinde fruto. Dado que INVU tiene un alto índice de cierre en negocios calificados, este riesgo es muy bajo. El referidor solo gana; nunca pierde.', 'Un referidor identifica un negocio potencial y lo registra. El negocio no cierra dentro de los 90 días por razones ajenas al referidor (el dueño decidió posponer la inversión). El referidor no pierde dinero; solo perdió 3 horas de su tiempo. Pero tiene otros contactos en su red y sigue refiriendo. Eventualmente, uno de sus referidos cierra y cobra su comisión. El riesgo es mínimo.', NULL, NULL, NULL, 42);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'La Comparación – Por qué INVU es Superior a Otros Programas', 'Otros programas de referidos tienen comisiones variables basadas en porcentaje (5-15%), condiciones de permanencia del cliente (6-12 meses), exigencia de participación en el proceso de venta, y sin protección de oportunidad. INVU ofrece comisiones fijas (S/500, S/1,000, S/1,500), sin condiciones de permanencia, sin exigencia de participación en ventas, y con protección de oportunidad por 90 días. El programa de INVU es más simple, más transparente y más rentable para el referidor.', 'Un referidor compara dos programas. En el programa X, la comisión es del 10% de la venta, pero el cliente debe permanecer 12 meses y el referidor debe ayudar en las demos. En INVU, la comisión es fija (S/1,000 para un negocio de 3 sedes), sin condiciones de permanencia, y el referidor solo abre la puerta. El referidor elige INVU porque es más simple y menos riesgoso.', NULL, NULL, NULL, 43);
INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) VALUES ('ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', 'El Potencial de Ingresos Ilimitado', 'El referidor puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Puede convertirlo en un ingreso recurrente si tiene una red de contactos activa en la industria gastronómica. El potencial de ingresos es ilimitado.', 'Un proveedor de insumos tiene una red de 50 clientes restauranteros. Refiere a 10 de ellos a INVU en un año. Si la mayoría son negocios de 3-5 sedes, gana S/1,000 por cada uno = S/10,000 anuales. Si algunos son cuentas consolidadas, gana S/1,500 por cada uno. El ingreso es significativo y el esfuerzo es compartido. El proveedor no tiene que vender; solo abrir la puerta.
